            container "Order API" "REST API that exposes order management functionality." "Spring Boot" {
                component "Order Service" "Coordinates order creation and state transitions."
                component "Order Repository" "Persists and retrieves order data."
                component "Payment Client" "Integrates with the Payment Gateway."
            }

            container "Order Database" "Stores order and line-item data." "PostgreSQL"

            container "Fulfilment Worker" "Processes confirmed orders and triggers fulfilment." "Java"
        }

        softwareSystem "Payment Gateway" "Third-party payment processing service." {
            tags "External"
        }

        softwareSystem "Email Service" "Third-party transactional email provider." {
            tags "External"
        }
`;

const relationships = `
        "Customer" -> "Web Store" "Places orders" "HTTPS"
        "Support Agent" -> "Order API" "Manages orders" "HTTPS"
        "Web Store" -> "Order API" "Submits and queries orders" "JSON/HTTPS"
        "Order API" -> "Order Database" "Reads and writes order data" "JDBC"
        "Order API" -> "Payment Gateway" "Charges cards" "HTTPS"
        "Fulfilment Worker" -> "Order Database" "Reads confirmed orders" "JDBC"
        "Fulfilment Worker" -> "Email Service" "Sends order confirmations" "SMTP"
`;

const views = `
    views {
        systemContext "Order Management" "SystemContext" "System context view of Order Management" {
            include *
            autoLayout
        }
        container "Order Management" "Containers" "Container view of Order Management" {
            include *
            autoLayout
        }
        component "Order API" "OrderApiComponents" "Component view of the Order API" {
            include *
            autoLayout
        }
        dynamic "PlaceOrder" "Dynamic view: placing an order" {
            include *
            autoLayout
        }
        theme default
    }
`;

const structureOnly = `workspace "Order Management" "An example multi-file Structurizr workspace assembled with !include." {
    model {${modelElements}
    }
}`;

const fullModel = `workspace "Order Management" "An example multi-file Structurizr workspace assembled with !include." {
    model {${modelElements}${relationships}
    }
${views}
}`;

const [structureValidate, structureInspect, fullValidate] = await Promise.allSettled([
  tools.structurizr.validate({ dsl: structureOnly }),
  tools.structurizr.inspect({ dsl: structureOnly }),
  tools.structurizr.validate({ dsl: fullModel }),
]);
const pick = (p) => p.status === "fulfilled" ? p.value : { error: String(p.reason) };
return {
  modelStructure_validate: pick(structureValidate),
  modelStructure_inspect: pick(structureInspect),
  fullModel_validate: pick(fullValidate),
};"}
